Properties p = new Properties();
p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "kafka-1:19092");
p.put(ConsumerConfig.GROUP_ID_CONFIG, "iso-demo");
p.put(ConsumerConfig.ISOLATION_LEVEL_CONFIG, "read_committed");
p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");

try (KafkaConsumer<String, String> c = new KafkaConsumer<>(p)) {
    c.subscribe(List.of("tx-a"));
    while (true) {
        ConsumerRecords<String, String> rs = c.poll(Duration.ofSeconds(1));
        for (ConsumerRecord<String, String> r : rs)
            System.out.printf("offset=%d value=%s%n", r.offset(), r.value());
    }
}
